head.script:
scwin.trigger1_onclick = function(e) {
    image1.setSrc("");
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. Script 탭 또는 Source 탭에서 scwin.trigger1_onclick 부분을 확인한다. 
    //1. Check the scwin.trigger1_onclick section in the Script tab or Source tab.    
    // verify step 1. image1.setSrc( '' );
    // Test step 2. 브라우저에서 개발자도구 (F12) 를 실행한다.
    //2. Launch the Developer Tool (F12) in your browser.    
    // verify step 2. 개발자도구가 실행된다.
    //2. The developer tool is launched.
    // Test step 3. setSrc('') 버튼을 클릭한다.
    //3. Click the setSrc ('') button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    // verify step 3. 아무반응이 없다. (그전버전에서는 src=/test/gridView_img/ 와 같이 하위경로가 입력됨)
    //3. There is no reaction. (In previous versions the subpath was entered as src = / test / gridView_img /)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'image1').getAttribute('src') == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 26-Jan-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
